/*Worked solution*/
sol2: if ta3=ta3a then "true" else "false";
sol3: if ta4=ta3a then "true" else "false";

/*Defining inequality system for question a*/
a: rand(3);
coef: rand([2,3,4]);
b: a+coef;
bb1: coef+1;

list1_cste: [a,a+1,a,a-1];
list2_cste: [-b,-b-1,-b-1,-b];
list3_cste: [a,a+1,a,a-1];
list4_cste: [-b,-b-1,-b-1,-b];
position_f: rand(4)+1;

aa: list1_cste[position_f];
bb: -list2_cste[position_f];
choices: makelist([i, is(i=position_f)], i, [1,2,3,4]);


ta1_x: aa;
ta1_y: bb;
ta1: matrix([aa],[bb]);
ta2: choices;

ordergreat(x, y);
/*Constrain coefficients*/
x1:1;
x2:1;
y1:rand(4)+2;
y2:y1-1;
aa:rand([8,9,10,11,12,13,14]);
bb:y2*aa+2+rand(3); /* keeps (0,aa) feasible and the intersection in the first quadrant */
/*Objective function coeffs*/
cc:(rand(3)+y1+2)*10; /* cc>10*y1 makes the intersection the unique optimum */
dd:cc-10;
obj:  cc*x+dd*y; /* Define the objective function */
/* Define Constraints */
ineq1: x1*x + x2*y <= aa;
ineq2: y1*x +y2*y <=bb;
ineq3: x >= 0;
ineq4: y >= 0;
/* Solve system to get corner points */
eq1: x1*x + x2*y = aa;
eq2: y1*x + y2*y = bb;

/* Solve eq1 for x */
x1_solution: rhs(solve(eq1, x)[1]);

/* Substitute x from eq1 into eq2 */
intersect_point: subst(x = x1_solution, eq2);

/* Solve for y */
solution_x2: rhs(solve(intersect_point, y)[1]);

/* Now substitute the solution of y back into eq1 to get x */
solution_x1: subst(y = solution_x2, x1_solution);

/* Final corner points */
intersection_point: [solution_x1, solution_x2];

/*Critical points and corresponding income at corner points*/
/* Define the income equation */
income_00: at(obj,[x=0,y=0]);
income_12:  at(obj,[x=0,y=aa]);
income_48: at(obj,[x=solution_x1, y=solution_x2]);
income_80: at(obj,[x=bb/y1, y=0]);
/* Store all the income values in a list */
income_values: [income_00, income_12, income_48, income_80];

/* Find the maximum income value */
max_income: apply(max, income_values);

/*Bounding box*/
xmin:-1;
ymax:aa+4;
xmax:aa+2;
ymin:-1;
eqnline1:(aa - x1*x)/x2;
eqnline2:(bb - y1*x)/y2;

test_income: is(max_income=income_48);

/*Model answers*/
ta1: random_permutation([["Maximization problem",true],["Minimization problem",false]]);
ta2: I=obj; /*objective function*/
ta3: ineq1; /*constraint on Work-hour constraint*/
ta4: ineq2; /*constraint on Preparation-hour constraint*/
ta6x: x>=0;
ta7y: y>=0;

/* Feedback helpers */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
objswap(s,t,u,v):= block([a:s,b:t],
  if not(atom(a)) and op(a)="=" and not(atom(b)) and op(b)="=" then (a:rhs(a), b:rhs(b)),
  if (not(atom(a)) and op(a)="=") or (not(atom(b)) and op(b)="=") then return(false),
  is(ratsimp(psubst([u=v,v=u],a)-b)=0) and not(is(ratsimp(a-b)=0)));

