questionvariables.text:
pasta_protein: 8;
tofu_protein:pasta_protein *2;
pasta_carbohydrates:60;
tofu_carbohydates:pasta_carbohydrates-20;
pasta_vitamin: 2;
tofu_vitamin:pasta_vitamin;
/*Objective function coeffs*/
pasta_cholesterol: pasta_carbohydrates;
tofu_cholesterol:pasta_cholesterol-10;
protein_needed:200;
carbohydates_needed:960;
vitamin_needed:40;
obj:  pasta_cholesterol*x+tofu_cholesterol*y; /* Define the objective function */
/* Define Constraints */
ineq1: pasta_protein*x + tofu_protein*y >=protein_needed;
ineq2: pasta_carbohydrates*x +tofu_carbohydates*y >=carbohydates_needed;
ineq3: pasta_vitamin*x+tofu_vitamin*y >=vitamin_needed;
ineq4: x >= 0;
ineq5: y >= 0;
/* Solve system to get corner points */
eq1: pasta_protein*x + tofu_protein*y =protein_needed;
const1:protein_needed/tofu_protein;
const2:carbohydates_needed/pasta_carbohydrates;
const3:vitamin_needed/pasta_vitamin;
eq2: pasta_carbohydrates*x +tofu_carbohydates*y =carbohydates_needed;
eq3: pasta_vitamin*x+tofu_vitamin*y =vitamin_needed;
/* Factor out the greatest common divisor (GCD) for simplification */
gcd1: gcd(lhs(eq1), rhs(eq1));
gcd2: gcd(lhs(eq2), rhs(eq2));
gcd3: gcd(lhs(eq3), rhs(eq3));

/* Simplified inequalities */
eq1_1: ratsimp(eq1/gcd1);
eq2_1: ratsimp(eq2/gcd2);
eq3_1: ratsimp(eq3/gcd3);
/* Solve for intersection points */
sol1: solve([eq1, eq2], [x, y]); /* Protein & Carbohydrate */
sol2: solve([eq2, eq3], [x, y]); /* Carbohydrate & Vitamin C */
sol3: solve([eq1, eq3], [x, y]); /* Protein & Vitamin C */

/* Solve for intercepts */
point_1: [0,  rhs(solve(subst(x=0,eq2), y)[1])]; /* Intersection with y-axis */
point_5: [rhs(solve(subst(y=0,eq1), x)[1]), 0]; /* Intersection with x-axis */

/* Extract numerical values */

point_3: [rhs(sol2[1][1]), rhs(sol2[1][2])];
point_4: [rhs(sol3[1][1]), rhs(sol3[1][2])];
point_origin:[0,0]; /*Default*/

/* Store all points */
points: [point_1, point_3, point_4, point_5];
/* Define the objective function */
obj(x, y) := pasta_cholesterol * x + tofu_cholesterol * y;

/* Evaluate the objective function at each point */
cholesterol_values: map(lambda([pt], [pt, obj(pt[1], pt[2])]), points);
/* Find the minimum cholesterol value */
min_cholesterol_value: lmin(map(lambda([entry], entry[2]), cholesterol_values));
min_point: lmin(map(lambda([entry], entry[2]), points));
optimal_point: point_3; /* vertex with the least cholesterol */

/* Display results */
cholesterol_values;
income_1:cholesterol_values[1][2];
income_2:cholesterol_values[2][2];
income_3:cholesterol_values[3][2];
income_4:cholesterol_values[4][2];


/*Model answers*/
ta1: random_permutation([["Maximization problem",false],["Minimization problem",true]]);
ta2: C=obj; /*objective function*/
ta3: ineq1; /*constraint on eating constraint*/
ta4: ineq2; /*constraint on eating constraint*/
ta5: ineq3;
ta6x: x>=0;
ta7y: y>=0;

/* Feedback helpers */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
objswap(s,t,u,v):= block([a:s,b:t],
  if not(atom(a)) and op(a)="=" and not(atom(b)) and op(b)="=" then (a:rhs(a), b:rhs(b)),
  if (not(atom(a)) and op(a)="=") or (not(atom(b)) and op(b)="=") then return(false),
  is(ratsimp(psubst([u=v,v=u],a)-b)=0) and not(is(ratsimp(a-b)=0)));

