questionvariables.text:
coefx:rand(4)+3;
coefy:if coefx=5 then rand(2)+1 else rand(3)+1; /* coefx=5, coefy=3 makes the objective parallel to constraint B */
constant1:rand_with_step(5,1200,5);
constant2:constant1+10;

obj: coefx*x+coefy*y;

const1: (coefx+7)*x+(coefy+1)*y>=constant1;
const11: (coefx+7)*x+(coefy+1)*y=constant1;
eqn1:rhs(solve(const11,y)[1]);
y_val:max(constant1/(coefy+1), constant2/(coefy+3)); /* vertex of the feasible region on the y-axis */

const2: (coefx+5)*x+(coefy+3)*y>=constant2;
const22: (coefx+5)*x+(coefy+3)*y=constant2;
eqn2:rhs(solve(const22,y)[1]);
x_val:max(constant1/(coefx+7), constant2/(coefx+5)); /* vertex of the feasible region on the x-axis */

aa:minimize_lp(obj, [const1, const2,x>=0,y>=0]);
z_val2: ev(obj,x=0,y=y_val);
z_val3: ev(obj,x=x_val,y=0);

/*Model answers*/
z:aa[1];/*C*/
y:subst(aa[2],y);/*N*/
x:subst(aa[2],x); /*M*/

y_val1:decimalplaces(y_val,2);
y_vals:round(y_val);
y_val_1:is(abs((y_vals-y_val1))=0.0);
y_val: if y_val_1=true then y_vals else y_val1;

x_val1:decimalplaces(x_val,2);
x_vals:round(x_val);
x_val_1:is(abs((x_vals-x_val1))=0.0);
x_val: if x_val_1=true then x_vals else x_val1;

z_val21:decimalplaces(z_val2,2);
z_vals2:round(z_val2);
z_val_21:is(abs((z_vals2-z_val21))=0.0);
z_val2: if z_val_21=true then z_vals2 else z_val21;

z_val31:decimalplaces(z_val3,2);
z_vals3:round(z_val3);
z_val_31:is(abs((z_vals3-z_val31))=0.0);
z_val3: if z_val_31=true then z_vals3 else z_val31;


y1:decimalplaces(y,2);
ys:round(y);
y_1:is(abs((ys-y1))=0.0);
y: if y_1=true then ys else y1;

x1:decimalplaces(x,2);
xs:round(x);
x_1:is(abs((xs-x1))=0.0);
x: if x_1=true then xs else x1;

z1:decimalplaces(z,2);
zs:round(z);
z_1:is(abs((zs-z1))=0.0);
z: if z_1=true then zs else z1;

/* Feedback helpers */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
objswap(s,t,u,v):= block([a:s,b:t],
  if not(atom(a)) and op(a)="=" and not(atom(b)) and op(b)="=" then (a:rhs(a), b:rhs(b)),
  if (not(atom(a)) and op(a)="=") or (not(atom(b)) and op(b)="=") then return(false),
  is(ratsimp(psubst([u=v,v=u],a)-b)=0) and not(is(ratsimp(a-b)=0)));

/* x + a*y <= p and b*x + y <= q meet at the integer point (xi, yi); a*b>1 keeps all four corners distinct */
xi: rand(4)+2; yi: rand(4)+2;
a: rand(3)+1;
b: if a=1 then rand(2)+2 else rand(3)+1;
p: xi+a*yi; q: b*xi+yi;
c1: x+a*y<=p; c2: b*x+y<=q;
ta1: [[0,0],[0,p/a],[xi,yi],[q/b,0]];
bmax: max(p, q)+1;

/* ---- shared helpers ---- */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
/* lp_ok: the student's point is feasible and optimal (allowing for 2 d.p. rounding) */
lp_ok(pt, vars, target, cons, best, sense) := block([v, tol],
  if not(listp(pt)) or length(pt)#length(vars) then return(false),
  if not(every(lambda([t], numberp(float(t))), pt)) then return(false),
  v: map("=", vars, pt),
  tol: 0.005*lsum(abs(coeff(expand(target),u)), u, vars) + 10^-6,
  is(abs(float(ev(target, v) - best)) <= tol)
    and every(lambda([c], block([d: float(ev(lhs(c)-rhs(c), v)), s: 0.005*lsum(abs(coeff(expand(lhs(c)),u)), u, vars) + 10^-6],
          if op(c)="<=" then is(d <= s) elseif op(c)=">=" then is(d >= -s) else is(abs(d) <= s))), cons)
    and every(lambda([t], is(float(t) >= -0.005)), pt));
/* relations equal up to a positive factor (same direction, same boundary line) */
relnorm(r):= block([d:expand(lhs(r)-rhs(r)), o:op(r)], if o=">=" then [">=", d] elseif o="<=" then [">=", -d] else [o, d]);
releq(a,b):= block([na, nb, q],
  if atom(a) or atom(b) or not(member(op(a),["<=",">=","="])) or not(member(op(b),["<=",">=","="])) then return(false),
  na: relnorm(a), nb: relnorm(b),
  if na[1]#nb[1] then return(false),
  if is(nb[2]=0) then return(is(na[2]=0)),
  q: ratsimp(na[2]/nb[2]),
  if not(constantp(q)) then return(false),
  if na[1]="=" then is(q#0) else is(q>0));
count_rel(sl, tl):= length(sublist(sl, lambda([s], some(lambda([t], releq(s,t)), tl))));

feedbackvariables.text:
sl: if listp(ans1) then ans1 else [];
okpts: sublist(sl, lambda([pt], listp(pt) and length(pt)=2 and some(lambda([v], near(pt[1],v[1],0.001) and near(pt[2],v[2],0.001)), ta1)));
ncorrect: length(unique(map(lambda([pt], [float(pt[1]), float(pt[2])]), okpts)));
nextra: length(sl) - length(okpts);
axiswrong: some(lambda([pt], listp(pt) and length(pt)=2 and ((near(pt[1],0,0.001) and near(pt[2],q,0.001)) or (near(pt[2],0,0.001) and near(pt[1],p,0.001)))), sl);

questionvariables.text:
a1: rand(3)+1; b1: rand(3)+1;
p1: a1*(rand(3)+3)+2*b1;
r: rand(3)+1;
c1: a1*x+b1*y<=p1;
c2: y<=x+r;
feas(pt):= is(a1*pt[1]+b1*pt[2]<=p1) and is(pt[2]<=pt[1]+r) and is(pt[1]>=0) and is(pt[2]>=0);
others: [[1,1],[2,0],[0,r+1],[1,r+2],[3,1],[0,r],[2,2],[4,0],[3,3],[1,0],[5,1],[2,-1]];
pts: random_permutation(append([[0,0],[-1,0]], rest(random_permutation(others), 8)));
ta1: makelist([k, feas(pts[k]), sconcat("\\((", pts[k][1], ", ", pts[k][2], ")\\)")], k, 1, 6);
okidx: sublist(makelist(k,k,1,6), lambda([k], feas(pts[k])));

/* ---- shared helpers ---- */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
/* lp_ok: the student's point is feasible and optimal (allowing for 2 d.p. rounding) */
lp_ok(pt, vars, target, cons, best, sense) := block([v, tol],
  if not(listp(pt)) or length(pt)#length(vars) then return(false),
  if not(every(lambda([t], numberp(float(t))), pt)) then return(false),
  v: map("=", vars, pt),
  tol: 0.005*lsum(abs(coeff(expand(target),u)), u, vars) + 10^-6,
  is(abs(float(ev(target, v) - best)) <= tol)
    and every(lambda([c], block([d: float(ev(lhs(c)-rhs(c), v)), s: 0.005*lsum(abs(coeff(expand(lhs(c)),u)), u, vars) + 10^-6],
          if op(c)="<=" then is(d <= s) elseif op(c)=">=" then is(d >= -s) else is(abs(d) <= s))), cons)
    and every(lambda([t], is(float(t) >= -0.005)), pt));
/* relations equal up to a positive factor (same direction, same boundary line) */
relnorm(r):= block([d:expand(lhs(r)-rhs(r)), o:op(r)], if o=">=" then [">=", d] elseif o="<=" then [">=", -d] else [o, d]);
releq(a,b):= block([na, nb, q],
  if atom(a) or atom(b) or not(member(op(a),["<=",">=","="])) or not(member(op(b),["<=",">=","="])) then return(false),
  na: relnorm(a), nb: relnorm(b),
  if na[1]#nb[1] then return(false),
  if is(nb[2]=0) then return(is(na[2]=0)),
  q: ratsimp(na[2]/nb[2]),
  if not(constantp(q)) then return(false),
  if na[1]="=" then is(q#0) else is(q>0));
count_rel(sl, tl):= length(sublist(sl, lambda([s], some(lambda([t], releq(s,t)), tl))));

