questionvariables.text:
opts: [[1, false, "bounded (a polygon)"], [2, false, "unbounded"], [3, false, "empty (no solutions)"]];
mk(t, a, p, q, k):= if t=1 then [a*x+y<=p, x<=q] elseif t=2 then [a*x+y>=p, y<=q] else [a*x+y<=p, a*x+y>=p+k];
tA: rand(3)+1; tB: rand(3)+1;
aA: rand(2)+1; pA: rand(5)+6; qA: rand(3)+2; kA: rand(3)+1;
aB: rand(2)+1; pB: rand(5)+6; qB: rand(3)+2; kB: rand(3)+1;
sysA: mk(tA, aA, pA, qA, kA);
sysB: mk(tB, aB, pB, qB, kB);
ta1: makelist([o[1], is(o[1]=tA), o[3]], o, opts);
ta2: makelist([o[1], is(o[1]=tB), o[3]], o, opts);
why(t):= if t=1 then "the region is enclosed: \\(y\\) is bounded by the first inequality and \\(x\\) by the second, so it is a polygon"
  elseif t=2 then "nothing stops \\(x\\) from growing: for large \\(x\\) every inequality holds, so the region extends without limit"
  else "the two inequalities contradict each other, since the same expression cannot be at most one number and at least a larger one";

