bb:rand(5)+2; /*The coefficient of x in the first constraint*/
a1:rand_with_prohib(2,6,[bb]); /*coefficient of x in the objective function (not parallel to constraint 1)*/
obj: a1*x+y;  /*The objective function*/
cc:rand(3)+4; /*The right hand side constant in the first contraint*/
const1_1:bb*x+y; /*The left hand side of the first contraint*/
const1:const1_1=cc; /*The first constraint*/
dd:rand(4)+2; /*The coefficient of y in the second constraint */
ee:floor(cc/bb)+1+rand(3); /*keeps all four listed vertices on the feasible region*/ /*The right hand side constant in the second contraint*/
const2: x+dd*y=ee; /*The second constraint*/
x_val2:(cc/bb); /*The value of x where the second constraint equation cuts the x axis*/
const2_2:cc-bb*x; /*The value y in the first constraint*/
const2_3:(ee-x)/dd; /*The value of y in the second contraint*/
x_val3:rhs(solve(const2_2=const2_3)[1]); /*The value of x when the two values of y are equated*/
y_val3:rhs(solve(subst(x_val3,x,const2))[1]); /*the value of y when the value of x is substituted in the second constraint*/
y_val4:ee/dd; /*The value of y where the first constraint equation cuts the y axis */
aa:maximize_lp(obj, [const1_1<=cc, x+dd*y<=ee, x>=0, y>=0]);
z:aa[1]; /*The maximum value of z*/
y:subst(aa[2],y);  /*The value of y at the maximum value Z*/
x:subst(aa[2],x); /*The value of x at the maximum value Z*/
z_1:decimalplaces(z,2);
y_1:decimalplaces(y,2);
x_1:decimalplaces(x,2);

/* Feedback helpers */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
objswap(s,t,u,v):= block([a:s,b:t],
  if not(atom(a)) and op(a)="=" and not(atom(b)) and op(b)="=" then (a:rhs(a), b:rhs(b)),
  if (not(atom(a)) and op(a)="=") or (not(atom(b)) and op(b)="=") then return(false),
  is(ratsimp(psubst([u=v,v=u],a)-b)=0) and not(is(ratsimp(a-b)=0)));

coefx:(rand(10)+2);
coefy:(rand(9)+3);
constant1:rand(10)+10;
constant2:rand(10);
coef:rand(min(5,coefy-1))+1; /* coef<coefy keeps Z bounded below with a unique minimum */

obj: coefx*x-coef*y;
const1: coefx*x+coefy*y>=constant1;
const11: coefx*x+coefy*y=constant1;
eqn1:rhs(solve(const11,y)[1]);
x_val:subst(0,y,rhs(solve(const11,x)[1]));
y_val:subst(0,x,rhs(solve(const11,y)[1]));
z_val: ev(obj,x=x_val,y=0);
const2: coefx*x-coefy*y>=constant2;
const22: coefx*x-coefy*y=constant2;
eqn2:rhs(solve(const22,y)[1]);
x_val2:subst(0,y,rhs(solve(const22,x)[1]));
aa:minimize_lp(obj, [const1, const2,x>=0,y>=0]);
z:aa[1];
y:subst(aa[2],y);
x:subst(aa[2],x);

