objswap(s,t,u,v):= block([a:s,b:t],
  if not(atom(a)) and op(a)="=" and not(atom(b)) and op(b)="=" then (a:rhs(a), b:rhs(b)),
  if (not(atom(a)) and op(a)="=") or (not(atom(b)) and op(b)="=") then return(false),
  is(ratsimp(psubst([u=v,v=u],a)-b)=0) and not(is(ratsimp(a-b)=0)));

/*Defining inequality system*/
a: rand([1,-1]);
b: -1;
c: 1;
d:1;
e: if a=1 then rand([1,2]) else rand([1,2,-1,-2]);
f: 1;
g: 1;
cst: rand([1,2]);
bb1: max(c,e,cst);
func1: a*y+b*x<=c;
func2: d*x<=e;
func3: f*y+g*x<cst;

/*Model answers*/
ta1: a*y+b*x=c;
ta2: d*x=e;
ta3: f*y+g*x=cst;

/* Order-free, form-independent comparison of equations/inequalities (used by the PRTs) */
nrel(r):=block([d:ratsimp(lhs(r)-rhs(r)),o:op(r)], if o=">=" then ["<=",-d] elseif o=">" then ["<",-d] else [o,d]);
releqv(a,b):= if atom(a) or atom(b) then false elseif op(a)="=" and op(b)="=" then (is(ratsimp(lhs(a)-rhs(a)-(lhs(b)-rhs(b)))=0) or is(ratsimp(lhs(a)-rhs(a)+(lhs(b)-rhs(b)))=0)) elseif op(a)="=" or op(b)="=" then false else is(nrel(a)=nrel(b));

