questionvariables.text:
/* coefficients of the objective function*/
coefx:(rand(10)+2); coefy:(rand(9)+1); coefz: rand(7)+coefx;
obj: coefx*x+coefy*y+coefz*z;

/*coefficients of the constraints*/
coef1x:rand(10); coef1y:rand(9); coef1z: rand(7); con1:rand_with_step(5,50,5);
coef2x:rand(10); coef2y:rand(9); coef2z: rand(7); con2:rand_with_step(1,50,4);
coef3x:1+rand(10); coef3y:1+rand(9); coef3z: 1+rand(7); /* positive: LP always bounded */ con3:rand_with_step(2,50,6);

const1: coef1x*x+coef1y*y+coef1z*z <= con1;
const2: coef2x*x+coef2y*y+coef2z*z <= con2;
const3: coef3x*x+coef3y*y+coef3z*z <= con3; 

aa:maximize_lp(obj, [const1, const2,const3,x>=0,y>=0,z>=0]);

ww: decimalplaces(aa[1],2);
xx: decimalplaces(subst(aa[2],x),2);
yy: decimalplaces(subst(aa[2],y),2);
zz: decimalplaces(subst(aa[2],z),2);
ta1:ww;
ta2: [xx,yy,zz];

del_1: rand_with_step(10,30,5);
aa1: 1+rand(10);
aa2: 2+rand(10);
del_const1: coef1x*x+coef1y*y+coef1z*z <= con1+del_1;
del_const2: (coef2x+aa1)*x+(coef2y+aa2)*y+coef2z*z <= con2;
del_const3: coef3x*x+coef3y*y+coef3z*z <= con3;

bb:maximize_lp(obj, [del_const1, del_const2, del_const3, x>=0, y>=0, z>=0]);

ww1: decimalplaces(bb[1],2);
xx1: decimalplaces(subst(bb[2],x),2);
yy1: decimalplaces(subst(bb[2],y),2);
zz1: decimalplaces(subst(bb[2],z),2);
ta3:ww1;
ta4: [xx1,yy1,zz1];

/* lp_ok: true if the student's point (entered to 2 d.p.) is feasible and optimal, allowing for rounding.
   Used by the PRTs so that any optimal point is accepted when the LP has alternative optima. */
lp_ok(pt, vars, target, cons, best, sense) := block([v, tol],
  if not(listp(pt)) or length(pt)#length(vars) then return(false),
  if not(every(lambda([t], numberp(float(t))), pt)) then return(false),
  v: map("=", vars, pt),
  tol: 0.005*lsum(abs(coeff(expand(target),u)), u, vars) + 10^-6,
  is(abs(float(ev(target, v) - best)) <= tol)
    and every(lambda([c], block([d: float(ev(lhs(c)-rhs(c), v)), s: 0.005*lsum(abs(coeff(expand(lhs(c)),u)), u, vars) + 10^-6],
          if sense="max" then is(d <= s) else is(d >= -s))), cons)
    and every(lambda([t], is(float(t) >= -0.005)), pt));

