questionvariables.text:
/* Generate random coefficients directly */

c1 : 2 * (rand(9) + 2);  /* even numbers 4..20 */
c2 : c1 + 2*(rand(c1/2-1)+1);  /* c1 < c2 < 2*c1 */

a11 : 1;
a12 : 2;
a21 : 1;
a22 : 1;

b2 : 10 * (rand(8) + 2); /* 20, 30, ..., 90 */
b1 : b2 + 10*(1+rand(b2/10-1)); /* b2 < b1 < 2*b2: the two-pivot solution is then always optimal */
/* Primal problem */
Z_primal : c1 * x1 + c2 * x2;
constraint1 : a11 * x1 + a12 * x2 >= b1;
constraint2 : a21 * x1 + a22 * x2 >= b2;

/* Dual problem */
Z_dual : b1 * y1 + b2 * y2;
dual_constraint1 : a11 * y1 + a21 * y2 <= c1;
dual_constraint2 : a12 * y1 + a22 * y2 <= c2;
dual_constraint1_1 : a11 * y1 + a21 * y2+s1 <= c1;
dual_constraint2_1 : a12 * y1 + a22 * y2+s2 <= c2;
/* Identify the minimum point*/
first_point:c1/a11;
second_point:c2/a12;
minimum_point:min(first_point,second_point);
/* Identify the Pivot row*/
pivot_row: if minimum_point =first_point then 1 else 2;
pivot_row_1: if pivot_row = 1 then a11 else a12;
s1:1; s2:1;a_11_1:a11/pivot_row_1; a_21_1:a21/pivot_row_1; s1_1:s1/pivot_row_1; c1_1:c1/pivot_row_1;
a_12_1:a12/pivot_row_1; a_22_1:a22/pivot_row_1; s2_1:s2/pivot_row_1; c2_1:c2/pivot_row_1;
dual_constraint_list1:[a_11_1,a_21_1,s1_1,0,0,c1_1];
dual_constraint_list2:[a_12_1,a_22_1,0,s2_1,0,c2_1];
dual_constraint_list: if pivot_row = 1 then dual_constraint_list1 else dual_constraint_list2;
row_1:[a11,a21,s1,0,0,c1];
row_2:[a12,a22,0,s2,0,c2];
new_row_1:row_1-dual_constraint_list;
new_row_2:dual_constraint_list;
first_element:-b1+(dual_constraint_list[1]*b1);second_element:-b2+(dual_constraint_list[2]*b1);third_element:0+(dual_constraint_list[3]*b1);fourth_element:0+(dual_constraint_list[4]*b1);sixth_element:0+(dual_constraint_list[6]*b1);fifth_element:1+(dual_constraint_list[5]*b1);
new_row_3:[first_element, second_element,third_element,fourth_element,fifth_element,sixth_element];

/* Find the maximum negative element */
max_nonneg : apply(min, new_row_3);

first_ratio:new_row_1[6]/new_row_1[2];second_ratio:new_row_2[6]/new_row_2[2];ratio:[first_ratio,second_ratio];min_ratio : apply(min, ratio);
new_row_1_1:denom(new_row_1[2])*new_row_1;
new_row_2_1:new_row_2-(new_row_2[2]*new_row_1_1);
new_row_3_1:new_row_3+(-max_nonneg*new_row_1_1); 
ta4:x1>=0;
ta5:x2>=0;
ta6_1:new_row_3_1[3];
ta6_2:new_row_3_1[4];
ta6:[ta6_1,ta6_2];
ta7:new_row_3_1[6];

