/* Generate random coefficients directly */

c1 : 2 * (rand(10) + 1);  /* Generates even numbers from 2 to 20 */
c2 : (2 * (rand(10) + 1))+2;  

a11 : 1+rand(3);
a12 : 2+rand(3);
a21 : 1+rand(4);
a22 :1+rand(5);

b2 : rand_with_step(10,90,4);
b1 : b2 + rand_with_step(10,30,2);

/* Primal problem */
Z_primal : c1 * x1 + c2 * x2;
constraint1 : a11 * x1 + a12 * x2 >= b1;
constraint2 : a21 * x1 + a22 * x2 >= b2;

/*solution of the primal problem*/
sol_p:minimize_lp(Z_primal, [constraint1, constraint2, x1>=0, x2>=0]);
z_opt: decimalplaces(sol_p[1],2);
xx1: decimalplaces(subst(sol_p[2],x1),2);
xx2: decimalplaces(subst(sol_p[2],x2),2);

/* Dual problem */
Z_dual : b1 * y1 + b2 * y2;
dual_constraint1 : a11 * y1 + a21 * y2 <= c1;
dual_constraint2 : a12 * y1 + a22 * y2 <= c2;
dual_constraint1_1 : a11 * y1 + a21 * y2+s1 <= c1;
dual_constraint2_1 : a12 * y1 + a22 * y2+s2 <= c2;

/*solution of the dual problem*/
sol_p:maximize_lp(Z_dual, [dual_constraint1, dual_constraint2, y1>=0, y2>=0]);
w_opt: decimalplaces(sol_p[1],2);
yy1: decimalplaces(subst(sol_p[2],y1),2);
yy2: decimalplaces(subst(sol_p[2],y2),2);

ta1: Z_dual;
ta2: dual_constraint1;
ta3: dual_constraint2;
ta4: [xx1,xx2];
ta5: z_opt;


