coords: [[0,2],[2,4],[2,0],[4,4],[4,0],[6,2]];
ew(u,v):= block([m: sublist(E, lambda([e], is(e[1]=u) and is(e[2]=v)))], if m=[] then inf else m[1][3]);
/* shortest distances in topological order (every arc goes from a lower to a higher node) */
d: [0, inf, inf, inf, inf, inf];
for v:2 thru 6 do d[v]: lmin(map(lambda([e], d[e[1]]+e[3]), sublist(E, lambda([e], is(e[2]=v)))));
dT: d[6];
/* one shortest path, by backtracking */
pth: [6];
for s_:1 thru 6 do if first(pth)#1 then pth: cons(first(sublist([1,2,3,4,5], lambda([u], is(ew(u,first(pth))#inf) and is(d[u]+ew(u,first(pth))=d[first(pth)])))), pth);
ta1: dT; ta2: pth;

