  if atom(a) or atom(b) or not(member(op(a),["<=",">=","="])) or not(member(op(b),["<=",">=","="])) then return(false),
  na: relnorm(a), nb: relnorm(b),
  if na[1]#nb[1] then return(false),
  if is(nb[2]=0) then return(is(na[2]=0)),
  q: ratsimp(na[2]/nb[2]),
  if not(constantp(q)) then return(false),
  if na[1]="=" then is(q#0) else is(q>0));
count_rel(sl, tl):= length(sublist(sl, lambda([s], some(lambda([t], releq(s,t)), tl))));

/* balanced: supplies are a random split of the total demand */
dm: makelist(rand_with_step(20,50,5), k, 1, 3);
tot: lsum(v, v, dm);
cut1: rand_with_step(10, tot-20, 5);
cut2: rand_with_step(cut1+5, tot-5, 5);
sp: [cut1, cut2-cut1, tot-cut2];
U: matrix([u11,u12,u13],[u21,u22,u23],[u31,u32,u33]);
tcost(Xm):= lsum(lsum(Cm[i,j]*Xm[i,j], j, [1,2,3]), i, [1,2,3]);
tcons: append(makelist(lsum(U[i,j], j, [1,2,3])=sp[i], i, 1, 3), makelist(lsum(U[i,j], i, [1,2,3])=dm[j], j, 1, 3),
              flatten(makelist(makelist(U[i,j]>=0, j, 1, 3), i, 1, 3)));
feasmat(Xm):= matrixp(Xm) and is(length(Xm)=3) and is(length(Xm[1])=3)
  and is(makelist(lsum(Xm[i,j], j, [1,2,3]), i, 1, 3)=sp) and is(makelist(lsum(Xm[i,j], i, [1,2,3]), j, 1, 3)=dm)
  and every(lambda([r], every(lambda([v], is(v>=0)), r)), args(Xm));

Cm: genmatrix(lambda([i,j], rand(11)+2), 3, 3);
nwc(sv, dv):= block([S:copylist(sv), D:copylist(dv), Xm:zeromatrix(3,3), i:1, j:1, q],
  while i<=3 and j<=3 do (q: min(S[i], D[j]), Xm[i,j]: q, S[i]: S[i]-q, D[j]: D[j]-q,
    if S[i]=0 then i:i+1 else j:j+1),
  Xm);
ta1: nwc(sp, dm);
ta2: tcost(ta1);
ta3: minimize_lp(tcost(U), tcons)[1];

/* ---- shared helpers ---- */
isnum(v):= numberp(float(v));
