vals: rest(random_permutation(makelist(k, k, 2, 16)), 6);
Cm: genmatrix(lambda([i,j], vals[3*(i-1)+j]), 3, 3);
lcm(sv, dv):= block([S:copylist(sv), D:copylist(dv), Xm:zeromatrix(3,3), rd:[false,false,false], cd:[false,false,false], best, bi, bj, q],
  for it:1 thru 9 do (
    best: inf,
    for i:1 thru 3 do for j:1 thru 3 do if not(rd[i]) and not(cd[j]) and is(Cm[i,j]<best) then (best: Cm[i,j], bi: i, bj: j),
    if best#inf then (q: min(S[bi], D[bj]), Xm[bi,bj]: q, S[bi]: S[bi]-q, D[bj]: D[bj]-q,
      if S[bi]=0 then rd[bi]: true, if D[bj]=0 then cd[bj]: true)),
