questionvariables.text:
cst: [rand(6)+4, rand(6)+4];
Am: genmatrix(lambda([i,j], rand(4)+1), 3, 2);
bv: [rand_with_step(12,30,2), rand_with_step(12,30,2), rand_with_step(12,30,2)];
Y: [y1,y2,y3];
pobj: cst[1]*x1+cst[2]*x2;
pcons: makelist(Am[i,1]*x1+Am[i,2]*x2>=bv[i], i, 1, 3);
ta1: bv[1]*y1+bv[2]*y2+bv[3]*y3;
ta2: Am[1,1]*y1+Am[2,1]*y2+Am[3,1]*y3<=cst[1];
ta3: Am[1,2]*y1+Am[2,2]*y2+Am[3,2]*y3<=cst[2];
