oldpt: [subst(old[2], x), subst(old[2], y)];
kk: max(1, floor(4*(oldpt[1]+oldpt[2])/5));
newc: x+y<=kk;
new: maximize_lp(obj, append(cons, [newc, x>=0, y>=0]));
ta1: new[1];
ta2: [subst(new[2], x), subst(new[2], y)];

/* ---- shared helpers ---- */
isnum(v):= numberp(float(v));
near(a,b,t):= isnum(a) and isnum(b) and is(abs(float(a-b)) < t);
/* lp_ok: the student's point is feasible and optimal (allowing for 2 d.p. rounding) */
lp_ok(pt, vars, target, cons, best, sense) := block([v, tol],
  if not(listp(pt)) or length(pt)#length(vars) then return(false),
  if not(every(lambda([t], numberp(float(t))), pt)) then return(false),
  v: map("=", vars, pt),
  tol: 0.005*lsum(abs(coeff(expand(target),u)), u, vars) + 10^-6,
  is(abs(float(ev(target, v) - best)) <= tol)
    and every(lambda([c], block([d: float(ev(lhs(c)-rhs(c), v)), s: 0.005*lsum(abs(coeff(expand(lhs(c)),u)), u, vars) + 10^-6],
          if op(c)="<=" then is(d <= s) elseif op(c)=">=" then is(d >= -s) else is(abs(d) <= s))), cons)
    and every(lambda([t], is(float(t) >= -0.005)), pt));
/* relations equal up to a positive factor (same direction, same boundary line) */
relnorm(r):= block([d:expand(lhs(r)-rhs(r)), o:op(r)], if o=">=" then [">=", d] elseif o="<=" then [">=", -d] else [o, d]);
releq(a,b):= block([na, nb, q],
  if atom(a) or atom(b) or not(member(op(a),["<=",">=","="])) or not(member(op(b),["<=",">=","="])) then return(false),
  na: relnorm(a), nb: relnorm(b),
  if na[1]#nb[1] then return(false),
  if is(nb[2]=0) then return(is(na[2]=0)),
  q: ratsimp(na[2]/nb[2]),
  if not(constantp(q)) then return(false),
  if na[1]="=" then is(q#0) else is(q>0));
count_rel(sl, tl):= length(sublist(sl, lambda([s], some(lambda([t], releq(s,t)), tl))));

/* ---- tableau tools: row 1 is the objective row, last column is the RHS ---- */
piv(T, r, c):= block([M: copymatrix(T), pv, f, m: length(T), n: length(T[1])],
  pv: M[r,c],
  for j:1 thru n do M[r,j]: M[r,j]/pv,
  for i:1 thru m do if i#r then (f: M[i,c], for j:1 thru n do M[i,j]: M[i,j]-f*M[r,j]),
  M);
/* dual simplex: leaving row = most negative RHS (lowest row on ties); 0 when the tableau is primal feasible */
dleave(T):= block([best:0, r:0, n: length(T[1])], for i:2 thru length(T) do if is(T[i,n]<best) then (best: T[i,n], r: i), r);
/* dual simplex: entering column = smallest |z_j / a_rj| over a_rj<0 (lowest column on ties); 0 when none: infeasible */
denter(T, r):= block([best:inf, c:0, q, n: length(T[1])], for j:1 thru n-1 do if is(T[r,j]<0) then (q: abs(T[1,j]/T[r,j]), if is(q<best) then (best: q, c: j)), c);
/* primal simplex (maximisation, z-row z - c.x = 0): entering = most negative z-row entry, leaving = minimum ratio */
penter(T):= block([best:0, c:0, n: length(T[1])], for j:1 thru n-1 do if is(T[1,j]<best) then (best: T[1,j], c: j), c);
pleave(T, c):= block([best:inf, r:0, q, n: length(T[1])], for i:2 thru length(T) do if is(T[i,c]>0) then (q: T[i,n]/T[i,c], if is(q<best) then (best: q, r: i)), r);
/* display with a header row and the basic variables down the side */
tabl(T, B, H):= apply(matrix, cons(H, makelist(cons(B[i], T[i]), i, 1, length(T))));
X: [x1,x2,x3,x4];
cv: makelist(rand(8)+2, k, 1, 4);
/* constraint 3 has only positive coefficients, so the problem is bounded */
Am: genmatrix(lambda([i,j], if i=3 then rand(5)+1 else rand(5)+1), 3, 4);
bv: makelist(rand_with_step(20, 60, 2), k, 1, 3);
obj: lsum(cv[j]*X[j], j, makelist(j,j,1,4));
cons: makelist(lsum(Am[i,j]*X[j], j, makelist(j,j,1,4))<=bv[i], i, 1, 3);
sol: maximize_lp(obj, append(cons, map(lambda([v], v>=0), X)));
ta1: sol[1];
ta2: map(lambda([v], subst(sol[2], v)), X);
ta3: makelist(bv[i]-lsum(Am[i,j]*ta2[j], j, makelist(j,j,1,4)), i, 1, 3);

